```javascript
/**
 * Chunks an array into smaller arrays of a specified size.
 *
 * @param {Array<any>} array The array to be chunked.
 * @param {number} n The desired size of each chunk. Must be a positive integer.
 * @returns {Array<Array<any>>} An array of arrays, where each inner array is a chunk of size n.
 * @throws {Error} If n is not a positive integer.
 */
function chunkArray(array, n) {
  if (typeof n !== 'number' || n <= 0 || !Number.isInteger(n)) {
    throw new Error("Chunk size 'n' must be a positive integer.");
  }

  const chunkedArray = [];
  let index = 0;

  while (index < array.length) {
    // Use slice to extract a portion of the array from the current index up to index + n
    const chunk = array.slice(index, index + n);
    chunkedArray.push(chunk);
    // Move the index forward by the chunk size
    index += n;
  }

  return chunkedArray;
}

