```javascript
/**
 * Checks if a given number is a prime number.
 * A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself.
 *
 * @param {number} num The number to check.
 * @returns {boolean} True if the number is prime, false otherwise.
 */
function isPrime(num) {
    // 1. Handle edge cases: Numbers less than or equal to 1 are not prime.
    if (num <= 1) {
        return false;
    }

    // 2. Handle the case for 2, which is the only even prime number.
    if (num === 2) {
        return true;
    }

    // 3. Handle even numbers greater than 2 (they are not prime).
    if (num % 2 === 0) {
        return false;
    }

    // 4. Check for divisibility from 3 up to the square root of the number,
    // only checking odd numbers (since we already excluded even numbers).
    // If a number 'n' has a divisor greater than sqrt(n), it must also have a divisor smaller than sqrt(n).
    const limit = Math.sqrt(num);
    for (let i = 3; i <= limit; i += 2) {
        if (num % i === 0) {
            return false;
        }
    }

    // If no divisors were found, the number is prime.
    return true;
}

// Example Usage:
