console.log(`The average of [${data2}] is: ${avg2}`); // Output: The average of [5,5,5,5] is: 5

const data3 = [];
const avg3 = calculateAverage(data3);
console.log(`The average of [] is: ${avg3}`); // Output: The average of [] is: 0

const data4 = [1, 2, 3, 4];
const avg4 = calculateAverage(data4);
console.log(`The average of [${data4}] is: ${avg4}`); // Output: The average of [1,2,3,4] is: 2.5
```

