     */
    increment() {
        this.count += 1;
        return this.count;
    }

    /**
     * Resets the counter back to 0.
     * @returns {number} The new value of the counter (which is 0).
     */
    reset() {
        this.count = 0;
        return this.count;
    }

    /**
