Here is a JavaScript function that implements a throttle mechanism for another function.

This implementation uses a closure to maintain the state of the last execution time and ensures that the function is only called at most once every specified delay.

```javascript
/**
 * Creates a throttled version of a function that only invokes it at most once
 * per every wait milliseconds.
 *
 * @param {Function} func The function to throttle.
 * @param {number} wait The number of milliseconds to wait between invocations.
 * @returns {Function} A new function that throttles the original function.
 */
function throttle(func, wait) {
  let timeout = null;
  let lastArgs = null;
  let lastThis = null;
  let lastExecTime = 0;

  return function(...args) {
    const context = this;
    const now = Date.now();

    // If it's the first call or enough time has passed since the last execution
    if (now - lastExecTime >= wait) {
      lastExecTime = now;
      func.apply(context, args);
    } else {
      // If it's within the wait period, we store the latest arguments
      // to be executed after the wait period is over.
      lastArgs = args;
      lastThis = context;

      // If there isn't an existing timeout, set one to execute the function
      // after the wait period. This ensures that if calls happen rapidly,
      // only the *last* call within the burst is executed after the delay.
      if (!timeout) {
        timeout = setTimeout(() => {
          lastExecTime = Date.now();
          timeout = null;
          // Execute the function with the last recorded arguments and context
          func.apply(lastThis, lastArgs);
          lastArgs = null;
          lastThis = null;
        }, wait - (now - lastExecTime)); // Calculate remaining time for better accuracy
      }
    }
  };
}

// --- Example Usage ---

// 1. The function we want to throttle
function logMessage(message) {
  console.log(`[${new Date().toLocaleTimeString()}] Logged: ${message}`);
}

// 2. Create a throttled version, limiting execution to once every 1000ms (1 second)
const throttledLog = throttle(logMessage, 1000);

console.log("Starting rapid calls...");

// Simulate rapid calls
throttledLog("Call 1");
throttledLog("Call 2");
throttledLog("Call 3");

// This call will be ignored immediately, but it will queue up
throttledLog("Call 4 (Should be queued)");

// Wait 500ms, then call again
setTimeout(() => {
  throttledLog("Call 5 (After 500ms)");
}, 500);

// Wait another 600ms (total 1100ms since the first call)
setTimeout(() => {
  throttledLog("Call 6 (After 1100ms - Should execute)");
}, 1100);
