/**
 * Finds the largest number in an array of numbers.
 *
 * @param numbers An array of numbers to search through.
 * @returns The largest number in the array, or -Infinity if the array is empty.
 */
function findLargestNumber(numbers: number[]): number {
  if (numbers.length === 0) {
    // Return -Infinity for an empty array, as it's the smallest possible number,
    // which is a reasonable sentinel value when no maximum exists.
    return -Infinity;
  }

  let largest: number = numbers[0];

  for (let i = 1; i < numbers.length; i++) {
    if (numbers[i] > largest) {
      largest = numbers[i];
    }
  }

  return largest;
}

