Here is a C function that computes the length of a singly linked list.

To make this function work, we first need to define the structure for a node in the linked list.

```c
#include <stdio.h>
#include <stdlib.h>

// Define the structure for a node in the linked list
typedef struct Node {
    int data;
    struct Node* next;
} Node;

/**
 * @brief Computes the length (number of nodes) of a linked list.
 *
 * @param head A pointer to the first node of the linked list.
 * @return The length of the linked list (an integer).
 */
int get_list_length(Node* head) {
    int count = 0;
    Node* current = head;

    // Traverse the list until the current pointer is NULL (end of the list)
    while (current != NULL) {
        count++;
        current = current->next;
    }

    return count;
}

// --- Example Usage ---
int main() {
    // 1. Create the linked list: 1 -> 2 -> 3 -> 4 -> NULL
    Node* head = (Node*)malloc(sizeof(Node));
    head->data = 1;
    head->next = (Node*)malloc(sizeof(Node));

    head->next->data = 2;
    head->next->next = (Node*)malloc(sizeof(Node));

    head->next->next->data = 3;
    head->next->next->next = (Node*)malloc(sizeof(Node));

    head->next->next->next->data = 4;
    head->next->next->next->next = NULL; // End of the list

    // Calculate the length
    int length = get_list_length(head);

    printf("The length of the linked list is: %d\n", length); // Expected output: 4

    // Test case 2: Empty list
    Node* empty_head = NULL;
    int empty_length = get_list_length(empty_head);
    printf("The length of the empty list is: %d\n", empty_length); // Expected output: 0

    // Clean up memory (important in real applications)
    Node* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }

    return 0;
}
```

### Explanation:

1.  **`struct Node`**: This structure defines the building block of the linked list. It contains an integer `data` and a pointer `next` which points to the subsequent node in the sequence.
2.  **`get_list_length(Node* head)`**:
    *   It initializes a counter variable `count` to `0`.
    *   It initializes a traversal pointer `current` to the `head` of the list.
    *   It enters a `while` loop that continues as long as `current` is not `NULL`. `NULL` signifies the end of the list.
    *   Inside the loop:
        *   `count` is incremented by 1 for every node visited.
        *   `current` is moved to the next node (`current = current->next;`).
    *   Once the loop finishes, `count` holds the total number of nodes, which is then returned.
