```c
#include <stdio.h>
#include <stddef.h> // For size_t

/**
 * @brief Copies a string from a source buffer to a destination buffer without using strcpy.
 *
 * This function iterates through the source string character by character
 * and copies them to the destination buffer until the null terminator is reached.
 *
 * @param destination The buffer where the string will be copied.
 * @param source The string to be copied from.
 * @return A pointer to the destination buffer.
 */
char* custom_strncpy(char* destination, const char* source) {
    if (destination == NULL || source == NULL) {
        return NULL;
    }

    int i = 0;
    // Iterate through the source string until the null terminator is found
    while (source[i] != '\0') {
        destination[i] = source[i];
        i++;
    }

    // Manually add the null terminator to the destination string
    destination[i] = '\0';

    return destination;
}

// Example usage:
int main() {
    char source[] = "Hello, World!";
    // Allocate enough space for the source string plus the null terminator
    char destination[100];

    printf("Original source string: \"%s\"\n", source);

    // Call the custom copy function
    char* copied_string = custom_strncpy(destination, source);

    if (copied_string != NULL) {
        printf("Copied string (using custom function): \"%s\"\n", copied_string);
    } else {
        printf("Error during string copy.\n");
    }

    // Test with an empty string
    char empty_source[] = "";
    char empty_dest[50];
    custom_strncpy(empty_dest, empty_source);
    printf("Copied empty string: \"%s\"\n", empty_dest);

    return 0;
}
```

