/// Calculates the sum of all even numbers in a given vector of integers.
///
/// # Arguments
///
/// * `numbers` - A vector of i32 integers.
///
/// # Returns
///
/// The sum of the even numbers found in the vector as an i32.
///
/// # Examples
///
/// ```
/// let data = vec![1, 2, 3, 4, 5, 6];
/// let sum = sum_even_numbers(&data);
/// assert_eq!(sum, 12); // 2 + 4 + 6 = 12
///
/// let empty_data: Vec<i32> = vec![];
/// let empty_sum = sum_even_numbers(&empty_data);
/// assert_eq!(empty_sum, 0);
/// ```
pub fn sum_even_numbers(numbers: &[i32]) -> i32 {
    numbers.iter()
           // Filter the iterator to keep only the even numbers
           .filter(|&n| n % 2 == 0)
           // Map the filtered numbers to their values (which are already i32)
           // and then sum them up.
           .sum()
}

fn main() {
