    let sum1 = sum_even_numbers(&data1);
    println!("The sum of even numbers in {:?} is: {}", data1, sum1); // Output: 12

    let data2 = vec![1, 3, 5, 7];
    let sum2 = sum_even_numbers(&data2);
    println!("The sum of even numbers in {:?} is: {}", data2, sum2); // Output: 0

    let data3: Vec<i32> = vec![10, 20, 31, 40];
    let sum3 = sum_even_numbers(&data3);
    println!("The sum of even numbers in {:?} is: {}", data3, sum3); // Output: 70
}
