    println!("The distance between P1 and P2 is: {}", dist);

    // Example 2: Distance to itself should be 0
    let p3 = Point::new(5.0, 5.0);
    let dist_self = p3.distance_to(&p3);
    println!("The distance between P3 and itself is: {}", dist_self);
}
