/// Finds the largest element in a slice of i32.
///
/// Returns `Some(largest_element)` if the slice is not empty,
/// and `None` if the slice is empty.
///
/// # Arguments
///
/// * `slice` - A slice of i32 values to search through.
///
/// # Returns
///
/// An `Option<i32>` containing the largest element, or `None` if the slice is empty.
pub fn find_largest(slice: &[i32]) -> Option<i32> {
    if slice.is_empty() {
        return None;
    }

    // Initialize the maximum value with the first element of the slice.
    let mut max_val = slice[0];

    // Iterate over the rest of the elements and update max_val if a larger element is found.
    for &item in slice.iter().skip(1) {
        if item > max_val {
            max_val = item;
        }
    }

    Some(max_val)
}

